 100%);\r\n  -webkit-box-shadow: 1px 2px 20px 0px rgba(255, 153, 0, 0.4);\r\n  box-shadow: 1px 2px 20px 0px rgba(255, 153, 0, 0.4);\r\n}\r\n\r\n.button:hover {\r\n  cursor: pointer;\r\n}\r\n\r\n.section_header {\r\n  margin-bottom: 8rem;\r\n  text-align: center;\r\n  text-transform: uppercase;\r\n}\r\n\r\n.section_header h2 {\r\n  font-size: 3rem;\r\n  line-height: 1.4;\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 700;\r\n  font-style: normal;\r\n  color: #333333;\r\n}\r\n\r\n.section_header_sub {\r\n  margin-top: 2rem;\r\n  margin-left: 50%;\r\n  -webkit-transform: translateX(-50%);\r\n  transform: translateX(-50%);\r\n  width: 17rem;\r\n  height: 0.2rem;\r\n  background: url(../img/glazing/line.png) 0 0 no-repeat;\r\n}\r\n\r\n.arrow {\r\n  position: absolute;\r\n  top: 50%;\r\n  -webkit-transform: translateY(-50%);\r\n  transform: translateY(-50%);\r\n  z-index: 99;\r\n  width: 2rem;\r\n  height: 2rem;\r\n  border: none;\r\n}\r\n\r\n.prev {\r\n  left: 0;\r\n  background: url(../img/glazing/left_arrow.png) center no-repeat;\r\n  background-size: 70%;\r\n}\r\n\r\n.next {\r\n  right: 0;\r\n  background: url(../img/glazing/right_arrow.png) center no-repeat;\r\n  background-size: 70%;\r\n}\r\n\r\n/*Header*/\r\n.header {\r\n  height: 10rem;\r\n  background-color: #ffffff;\r\n  /*border: 1px solid red;*/\r\n}\r\n\r\n.header .logo {\r\n  height: 10rem;\r\n  display: table;\r\n}\r\n\r\n.header .logo_img {\r\n  display: table-cell;\r\n  vertical-align: middle;\r\n}\r\n\r\n.header .logo_img img {\r\n  width: 12vw;\r\n}\r\n\r\n.header .logo p {\r\n  display: table-cell;\r\n  vertical-align: middle;\r\n  line-height: 1.2;\r\n  font-size: 1.4rem;\r\n  color: #0089cd;\r\n}\r\n\r\n.header_btn {\r\n  background: #ffffff url(../img/header/edit.png) 1rem center no-repeat;\r\n  padding: 1rem 1rem 1rem 5rem;\r\n  border: 2px solid #55a831;\r\n  border-radius: 1rem;\r\n  background-color: #ffffff;\r\n  font-size: 1.4rem;\r\n  line-height: 1.2;\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 700;\r\n  font-style: normal;\r\n  color: #55a831;\r\n  /*p {\r\n\t\t\t\tdisplay: inline-block;\r\n\t\t\tvertical-align: top;\r\n\t\t\t\tfont-size: 1.4rem;\r\n\t\t\t\tline-height: 1.2;\r\n\t\t\t\t.bold();\r\n\t\t\t\tcolor: @green;\r\n\t\t\t}*/\r\n}\r\n\r\n.header_btn_wrap {\r\n  display: table;\r\n  width: 100%;\r\n  height: 10rem;\r\n}\r\n\r\n.header_btn_wrap_block {\r\n  display: table-cell;\r\n  vertical-align: middle;\r\n}\r\n\r\n.header_btn_wrap_block img {\r\n  margin-right: 0.7rem;\r\n}\r\n\r\n.header_btn:hover {\r\n  cursor: pointer;\r\n}\r\n\r\n.header .working_hours {\r\n  height: 10rem;\r\n  display: table;\r\n  /*text-align: right;*/\r\n}\r\n\r\n.header .working_hours_img {\r\n  display: table-cell;\r\n  vertical-align: middle;\r\n}\r\n\r\n.header .working_hours_img img {\r\n  margin-right: 2rem;\r\n}\r\n\r\n.header .working_hours p {\r\n  display: table-cell;\r\n  vertical-align: middle;\r\n  font-size: 1.4rem;\r\n  color: #333333;\r\n}\r\n\r\n.header .working_hours p span {\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 700;\r\n  font-style: normal;\r\n  font-size: 1.8rem;\r\n}\r\n\r\n.header .contact_us {\r\n  height: 10rem;\r\n  display: table;\r\n  text-align: right;\r\n}\r\n\r\n.header .contact_us_wrap {\r\n  display: table-cell;\r\n  vertical-align: middle;\r\n  line-height: 1.7;\r\n}\r\n\r\n.header .contact_us_wrap a {\r\n  display: block;\r\n  font-size: 2.3rem;\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 700;\r\n  font-style: normal;\r\n  color: #333333;\r\n  /*border: 1px solid blue;*/\r\n}\r\n\r\n.header .contact_us_wrap a img {\r\n  margin-right: 1rem;\r\n}\r\n\r\n.header .contact_us_wrap .phone_link {\r\n  font-size: 1.5rem;\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 400;\r\n  font-style: normal;\r\n  color: #0089cd;\r\n  text-decoration: underline;\r\n}\r\n\r\n/*Main*/\r\n.main {\r\n  padding: 10rem 0;\r\n  background: #ffffff url(../img/main/bg.png) 0 0 no-repeat;\r\n  background-size: cover;\r\n}\r\n\r\n.main h1 {\r\n  margin: 0;\r\n  /*margin-top: -4rem;*/\r\n  font-size: 5.5rem;\r\n  line-height: 1.5;\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 700;\r\n  font-style: normal;\r\n  color: #fff;\r\n  text-shadow: -4px 2px 13px #333;\r\n}\r\n\r\n.main h1 span {\r\n  font-size: 2.6rem;\r\n}\r\n\r\n.main_features {\r\n  padding: 0;\r\n  margin-top: 13rem;\r\n}\r\n\r\n.main_features_block {\r\n  text-align: center;\r\n}\r\n\r\n.main_features_block .small_img {\r\n  margin-top: 1rem;\r\n}\r\n\r\n.main_features_block p {\r\n  margin-top: -6rem;\r\n  font-size: 1.3rem;\r\n  line-height: 1.3;\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 700;\r\n  font-style: normal;\r\n  text-transform: uppercase;\r\n  color: #ffffff;\r\n}\r\n\r\n.main_form {\r\n  margin-top: 2rem;\r\n}\r\n\r\n/*glazing*/\r\n.glazing {\r\n  padding: 8rem 0;\r\n}\r\n\r\n.glazing_block {\r\n  display: inline-block;\r\n}\r\n\r\n.glazing_block img {\r\n  display: block;\r\n  margin: 0 auto;\r\n  margin-bottom: 2rem;\r\n}\r\n\r\n.glazing_block a {\r\n  font-size: 1.8rem;\r\n  font-weight: 600;\r\n  text-decoration: underline;\r\n  /*&:focus {\r\n\t\t\t\ttext-decoration: none;\r\n\t\t\t\tcolor: #454545;\r\n\t\t\t}*/\r\n}\r\n\r\n.glazing_block a:hover {\r\n  cursor: pointer;\r\n}\r\n\r\n.glazing_cold {\r\n  margin-top: 4rem;\r\n  padding: 2.5rem 0;\r\n  text-align: center;\r\n  border-bottom-left-radius: 5px;\r\n  border-top-left-radius: 5px;\r\n  border-top: 0.5rem solid #0089cd;\r\n  background: -webkit-gradient(\r\n    linear,\r\n    left top,\r\n    left bottom,\r\n    from(#c7dce9),\r\n    color-stop(0%, #c7dce9),\r\n    to(rgba(255, 255, 255, 0))\r\n  );\r\n  background: linear-gradient(\r\n    180deg,\r\n    #c7dce9 0%,\r\n    #c7dce9 0%,\r\n    rgba(255, 255, 255, 0) 100%\r\n  );\r\n}\r\n\r\n.glazing_cold h3 {\r\n  margin-bottom: 2.5rem;\r\n  font-size: 2rem;\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 700;\r\n  font-style: normal;\r\n  text-transform: uppercase;\r\n  color: #0089cd;\r\n}\r\n\r\n.glazing_warm {\r\n  margin-top: 4rem;\r\n  padding: 2.5rem 0;\r\n  text-align: center;\r\n  border-bottom-right-radius: 5px;\r\n  border-top-right-radius: 5px;\r\n  border-top: 0.5rem solid #ffb903;\r\n  background: -webkit-gradient(\r\n    linear,\r\n    left top,\r\n    left bottom,\r\n    from(#f7eac9),\r\n    color-stop(0%, #f7eac9),\r\n    to(rgba(255, 255, 255, 0))\r\n  );\r\n  background: linear-gradient(\r\n    180deg,\r\n    #f7eac9 0%,\r\n    #f7eac9 0%,\r\n    rgba(255, 255, 255, 0) 100%\r\n  );\r\n}\r\n\r\n.glazing_warm h3 {\r\n  margin-bottom: 2.5rem;\r\n  font-size: 2rem;\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 700;\r\n  font-style: normal;\r\n  text-transform: uppercase;\r\n  color: #ffb903;\r\n}\r\n\r\n.glazing ul {\r\n  margin-top: 3.7rem;\r\n  padding: 0 6rem;\r\n  font-size: 1.4rem;\r\n  font-weight: 400;\r\n  list-style: none;\r\n  line-height: 2.1;\r\n  text-align: left;\r\n}\r\n\r\n.glazing ul li:before {\r\n  content: \"\";\r\n  display: inline-block;\r\n  margin-right: 1.7rem;\r\n  width: 2.5rem;\r\n  height: 2.5rem;\r\n  background: url(../img/glazing/check.png) no-repeat center;\r\n  background-size: 100%;\r\n  vertical-align: middle;\r\n}\r\n\r\n.glazing_price {\r\n  padding: 0 6rem;\r\n}\r\n\r\n.glazing_price p {\r\n  display: inline-block;\r\n  margin-right: 3rem;\r\n  vertical-align: middle;\r\n  font-size: 2rem;\r\n  line-height: 1.7;\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 700;\r\n  font-style: normal;\r\n}\r\n\r\n.glazing_price p span {\r\n  font-size: 1.4rem;\r\n  font-family: \"Open Sans\", sans-serif;\r\n  font-weight: 400;\r\n  font-style: normal;\r\n}\r\n\r\n.glazing_price_btn {\r\n  padding: 2rem 2rem;\r\n}\r\n\r\n.glazing .aluminum,\r\n.glazing .plastic,\r\n.glazing .french,\r\n.glazing .rise {\r\n  display: none;\r\n}\r\n\r\n.glazing a.active {\r\n  text-decoration: none;\r\n 